/**
 * [NAME] Landing — particle morph targets.
 *
 * Targets are generated by drawing a shape/glyph on an offscreen canvas,
 * sampling its opaque pixels, and mapping N samples onto a unit sphere.
 * All targets share the same point count so a single `uMorph` uniform can
 * interpolate between them (sphere -> square outline -> "</>" glyph).
 */

import { generateFibonacciSphereBuffer } from "@/lib/particleEngine";

const CANVAS_SIZE = 512;

/** Deterministically pick `count` samples from `candidates`. */
function subsample(candidates: Array<{ x: number; y: number }>, count: number): Array<{ x: number; y: number }> {
  if (candidates.length <= count) return candidates;
  const out: Array<{ x: number; y: number }> = [];
  const stride = candidates.length / count;
  for (let i = 0; i < count; i++) {
    out.push(candidates[Math.floor(i * stride)]);
  }
  return out;
}

/** Map 2D samples in [-1, 1] onto unit-sphere directions. */
function mapToSphere(samples: Array<{ x: number; y: number }>): Float32Array {
  const out = new Float32Array(samples.length * 3);
  for (let i = 0; i < samples.length; i++) {
    const i3 = i * 3;
    const x = samples[i].x;
    const y = samples[i].y;
    // Flatten toward the sphere surface so the glyph reads as a shell shape.
    const z = 0.25 * (Math.random() * 2 - 1);
    const len = Math.sqrt(x * x + y * y + z * z) || 1;
    out[i3] = x / len;
    out[i3 + 1] = y / len;
    out[i3 + 2] = z / len;
  }
  return out;
}

/** Fibonacci sphere distribution (shared with the hero sphere). */
export function spherePoints(count: number): Float32Array {
  return generateFibonacciSphereBuffer(count, { jitter: 0.02, surfaceBias: 1.0, seed: 104729 });
}

/** Square outline: points distributed along the perimeter of a unit square. */
export function squareOutlinePoints(count: number): Float32Array {
  const out = new Float32Array(count * 3);
  const perSide = Math.max(2, Math.floor(count / 4));
  let i = 0;
  const sides: Array<(t: number) => { x: number; y: number }> = [
    (t) => ({ x: -1 + 2 * t, y: -1 }), // bottom
    (t) => ({ x: 1, y: -1 + 2 * t }), // right
    (t) => ({ x: 1 - 2 * t, y: 1 }), // top
    (t) => ({ x: -1, y: 1 - 2 * t }), // left
  ];
  let side = 0;
  while (i < count) {
    const fn = sides[side % 4];
    const t = (i % perSide) / Math.max(1, perSide - 1);
    const p = fn(t);
    const len = Math.sqrt(p.x * p.x + p.y * p.y) || 1;
    out[i * 3] = p.x / len;
    out[i * 3 + 1] = p.y / len;
    out[i * 3 + 2] = 0;
    i += 1;
    if (i % perSide === 0) side += 1;
  }
  return out;
}

/**
 * Glyph points: draw `text` on an offscreen canvas, sample opaque pixels,
 * and map them to `count` points.
 */
export function glyphPoints(text: string, count: number): Float32Array {
  const canvas = document.createElement("canvas");
  canvas.width = CANVAS_SIZE;
  canvas.height = CANVAS_SIZE;
  const ctx = canvas.getContext("2d");
  if (!ctx) return spherePoints(count);

  ctx.fillStyle = "#FFFFFF";
  ctx.textBaseline = "middle";
  ctx.textAlign = "center";
  // Fit the glyph to ~70% of the canvas.
  let fontSize = CANVAS_SIZE * 0.6;
  ctx.font = `bold ${fontSize}px "Plus Jakarta Sans", sans-serif`;
  while (ctx.measureText(text).width > CANVAS_SIZE * 0.7 && fontSize > 10) {
    fontSize -= 2;
    ctx.font = `bold ${fontSize}px "Plus Jakarta Sans", sans-serif`;
  }
  ctx.fillText(text, CANVAS_SIZE / 2, CANVAS_SIZE / 2);

  const imageData = ctx.getImageData(0, 0, CANVAS_SIZE, CANVAS_SIZE);
  const data = imageData.data;
  const candidates: Array<{ x: number; y: number }> = [];

  // Sample every 4th pixel for speed; keep only opaque alpha.
  const step = 4;
  for (let y = 0; y < CANVAS_SIZE; y += step) {
    for (let x = 0; x < CANVAS_SIZE; x += step) {
      const alpha = data[(y * CANVAS_SIZE + x) * 4 + 3];
      if (alpha > 128) {
        candidates.push({
          x: (x / CANVAS_SIZE) * 2 - 1,
          y: -((y / CANVAS_SIZE) * 2 - 1), // flip Y (canvas Y is down)
        });
      }
    }
  }

  const samples = subsample(candidates, count);
  // If the glyph drew nothing (font not loaded yet), fall back to a sphere.
  if (samples.length === 0) return spherePoints(count);
  return mapToSphere(samples);
}

export type MorphTargetName = "sphere" | "square" | "glyph";

/** Build all morph targets for `count` points. */
export function buildMorphTargets(
  count: number,
  glyphText: string
): Record<MorphTargetName, Float32Array> {
  return {
    sphere: spherePoints(count),
    square: squareOutlinePoints(count),
    glyph: glyphPoints(glyphText, count),
  };
}
